import subprocess

def handle(query, state):
    cmd = (query.get("cmd") or [""])[0]
    if not cmd:
        return 400, {"Content-Type": "text/plain"}, "Missing cmd parameter"

    try:
        result = subprocess.run(
            "echo " + cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=5
        )
        output = result.stdout.strip()
        return 200, {"Content-Type": "text/plain"}, output
    except subprocess.TimeoutExpired:
        return 500, {"Content-Type": "text/plain"}, "Command timeout"
    except Exception as e:
        return 500, {"Content-Type": "text/plain"}, f"Error: {str(e)}"
